-- CWP-01 Master Canonical Wine Catalog seed
-- Source: D:\Descargas\Phone Link\WSET3_rebuilt.md
-- Source SHA256: 91B5D64859140AF5C98EDE988D2F55D52579B3C8DCD5004EE225A9B62569CC25
create table if not exists public.canonical_wines (
  canonical_id text primary key,
  wine_family text not null,
  wine_style text not null,
  display_name text not null,
  wine_name text not null,
  wine_type text not null,
  country text not null,
  region text not null,
  subregion text,
  appellation text,
  priority integer not null,
  wset_importance text not null,
  practice_priority integer not null,
  difficulty_score integer not null,
  confidence_score numeric not null,
  display_label text not null,
  source jsonb not null,
  canonical_source jsonb not null,
  canonical jsonb not null
);

ON CONFLICT (canonical_id) DO UPDATE SET
  wine_family = excluded.wine_family,
  wine_style = excluded.wine_style,
  display_name = excluded.display_name,
  wine_name = excluded.wine_name,
  wine_type = excluded.wine_type,
  country = excluded.country,
  region = excluded.region,
  subregion = excluded.subregion,
  appellation = excluded.appellation,
  priority = excluded.priority,
  wset_importance = excluded.wset_importance,
  practice_priority = excluded.practice_priority,
  difficulty_score = excluded.difficulty_score,
  confidence_score = excluded.confidence_score,
  display_label = excluded.display_label,
  source = excluded.source,
  canonical_source = excluded.canonical_source,
  canonical = excluded.canonical;
